#include <iostream>
#include <vector>
using namespace std;

long long N, K;
const long long MOD = 1000000007LL;

vector<vector<vector<vector<long long>>>> S, A, P;
vector<vector<long long>> Res, Aux;
vector<long long> Power;

void copyMat(vector<vector<long long>>& dest, const vector<vector<long long>>& src) {
    for (size_t i = 0; i < dest.size(); ++i)
        for (size_t j = 0; j < dest.size(); ++j)
            dest[i][j] = src[i][j];
}

inline void addMod(long long& a, long long b) {
    a = (a + b) % MOD;
}

void matMul(const vector<vector<long long>>& mat1, const vector<vector<long long>>& mat2, vector<vector<long long>>& res, long long n, long long m, long long p) {
    for (long long i = 0; i < n; ++i) {
        for (long long j = 0; j < p; ++j) {
            res[i][j] = 0;
            for (long long k = 0; k < m; ++k) {
                addMod(res[i][j], (mat1[i][k] * mat2[k][j]) % MOD);
            }
        }
    }
}

void precomputeA() {
    for (long long x = 0; x < K; ++x) {
        for (long long i = 0; i < K + 1; ++i) {
            A[0][x][i][i] = 1;
        }
        for (long long j = 0; j < K + 1; ++j) {
            A[0][x][j][x] = 1;
        }
    }

    copyMat(P[0][0], A[0][0]);
    copyMat(S[0][K - 1], A[0][K - 1]);

    for (long long x = 1; x < K; ++x) {
        matMul(P[0][x - 1], A[0][x], P[0][x], K + 1, K + 1, K + 1);
    }

    for (long long x = K - 2; x >= 0; --x) {
        matMul(A[0][x], S[0][x + 1], S[0][x], K + 1, K + 1, K + 1);
    }

    long long multiplier = 1;
    int level = 0;
    while (multiplier <= N / K) {
        for (long long x = 0; x < K; ++x) {
            if (x > 0) {
                copyMat(A[level][x], S[level - 1][x]);
                matMul(A[level][x], P[level - 1][x - 1], Aux, K + 1, K + 1, K + 1);
                copyMat(A[level][x], Aux);
            } else {
                copyMat(A[level][x], S[level - 1][x]);
            }
        }
        copyMat(P[level][0], A[level][0]);
        copyMat(S[level][K - 1], A[level][K - 1]);

        for (long long x = 1; x < K; ++x) {
            matMul(P[level][x - 1], A[level][x], P[level][x], K + 1, K + 1, K + 1);
        }

        for (long long x = K - 2; x >= 0; --x) {
            matMul(A[level][x], S[level][x + 1], S[level][x], K + 1, K + 1, K + 1);
        }

        if (multiplier > N / K / K) break;
        multiplier *= K;
        ++level;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> N >> K;

    Power.push_back(1);
    while (Power.back() <= N / K) {
        Power.push_back(Power.back() * K);
    }

    int levels = Power.size() - 1;

    S.assign(levels + 1, vector<vector<long long>>(K, vector<long long>(K + 1, vector<long long>(K + 1, 0))));
    A.assign(levels + 1, vector<vector<long long>>(K, vector<long long>(K + 1, vector<long long>(K + 1, 0))));
    P.assign(levels + 1, vector<vector<long long>>(K, vector<long long>(K + 1, vector<long long>(K + 1, 0))));
    Res.assign(K + 1, vector<long long>(K + 1, 0));
    Aux.assign(K + 1, vector<long long>(K + 1, 0));

    precomputeA();

    long long remaining = N;
    int digitIndex = 0;
    Res[0][K] = 1;

    for (int p = levels; p >= 0; --p) {
        while (Power[p] <= remaining) {
            matMul(Res, A[p][digitIndex], Aux, K + 1, K + 1, K + 1);
            copyMat(Res, Aux);
            digitIndex = (digitIndex + 1) % K;
            remaining -= Power[p];
        }
    }

    long long answer = 0;
    for (int i = 0; i <= K; ++i) {
        addMod(answer, Res[0][i]);
    }
    cout << answer << '\n';
    return 0;
}
